<?php
namespace App\Http\Controllers;
use App\Models\StudyBuddyVerificationCase;use Illuminate\Http\RedirectResponse;use Illuminate\Http\Request;use Illuminate\Validation\Rule;use Illuminate\View\View;
class StudyBuddyVerificationController extends Controller{public function show(Request $r):View{$user=$r->user();$cases=StudyBuddyVerificationCase::where('user_id',$user->id)->latest()->take(10)->get();return view('studybuddy.verification.center',compact('user','cases'));} public function submit(Request $r):RedirectResponse{$user=$r->user();$d=$r->validate(['role_type'=>['required',Rule::in(['adult_account','parent_guardian','teacher','independent_learner'])],'method'=>['required',Rule::in(['face_liveness_provider','manual_id_review','school_email_domain','guardian_review'])],'provider_reference'=>['nullable','string','max:190'],'submitted_name'=>['required','string','max:190'],'submitted_country'=>['nullable','string','max:100'],'notes'=>['nullable','string','max:1000'],'adult_confirmed'=>['required','accepted'],'consent_confirmed'=>['required','accepted']]);if(!$user->isAdult())return back()->withErrors(['adult_confirmed'=>'Adult verification is only available for accounts whose date of birth is 18+.'])->withInput();if(StudyBuddyVerificationCase::where('user_id',$user->id)->whereIn('status',['pending','needs_more_info'])->exists())return back()->withErrors(['role_type'=>'You already have a verification case waiting for review.'])->withInput();StudyBuddyVerificationCase::create(['user_id'=>$user->id,'role_type'=>$d['role_type'],'method'=>$d['method'],'status'=>'pending','provider_reference'=>$d['provider_reference']??null,'submitted_name'=>$d['submitted_name'],'submitted_country'=>$d['submitted_country']??null,'adult_confirmed'=>true,'consent_confirmed'=>true,'notes'=>$d['notes']??null,'submitted_at'=>now()]);$user->update(['adult_verification_status'=>'pending','adult_verification_method'=>$d['method'],'adult_verification_reference'=>$d['provider_reference']??null,'adult_verification_consent_at'=>now(),'adult_verification_submitted_at'=>now(),'role_verification_status'=>in_array($user->role,['parent','teacher','independent_learner'],true)?'pending_admin_review':$user->role_verification_status]);return back()->with('status','Verification request submitted. An admin can now review it safely.');} public function adminIndex():View{$cases=StudyBuddyVerificationCase::with('user')->latest()->paginate(25);return view('admin.studybuddy.verifications.index',compact('cases'));} public function adminUpdate(Request $r,StudyBuddyVerificationCase $case):RedirectResponse{$d=$r->validate(['status'=>['required',Rule::in(['pending','verified','rejected','needs_more_info'])],'admin_notes'=>['nullable','string','max:2000']]);$case->update(['status'=>$d['status'],'admin_notes'=>$d['admin_notes']??null,'reviewed_by'=>$r->user()->id,'reviewed_at'=>now()]);$u=$case->user;if($u&&$d['status']==='verified')$u->update(['adult_verification_status'=>'verified','adult_verification_method'=>$case->method,'adult_verification_reference'=>$case->provider_reference,'adult_verification_reviewed_at'=>now(),'age_verified_at'=>now(),'role_verified_at'=>now(),'role_verification_status'=>'verified']);elseif($u&&$d['status']==='rejected')$u->update(['adult_verification_status'=>'rejected','adult_verification_reviewed_at'=>now(),'role_verification_status'=>$u->needsAdultVerification()?'rejected':$u->role_verification_status]);elseif($u&&$d['status']==='needs_more_info')$u->update(['adult_verification_status'=>'needs_more_info','role_verification_status'=>$u->needsAdultVerification()?'needs_more_info':$u->role_verification_status]);return back()->with('status','Verification case updated.');}}
